# The C extension is generated by cffi from python/crag/_build.py (API mode);
# everything else lives in pyproject.toml.
#
# cffi's own `cffi_modules=` hook hands setuptools absolute source paths,
# which setuptools rejects, so the Extension is built here and its paths
# are made relative to this directory (the repository root).
import os
import sys

from setuptools import setup

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "python", "crag"))
from _build import ffibuilder  # noqa: E402

ext = ffibuilder.distutils_extension(tmpdir=os.path.join("build", "cffi"))
here = os.path.dirname(os.path.abspath(__file__))
ext.sources = [os.path.relpath(s, here) for s in ext.sources]
ext.include_dirs = [os.path.relpath(d, here) if os.path.isabs(d) else d
                    for d in ext.include_dirs]

setup(ext_modules=[ext])
